const expectedKey = env.get("ECODORM_API_KEY");
const receivedKey = msg.req?.headers?.["x-api-key"];

// สร้าง HTTP Response สำหรับตอบ ESP32
function respond(code, body) {
    msg.statusCode = code;
    msg.headers = { "Content-Type": "application/json" };
    msg.payload = body;

    // Output 1 ไม่ส่งข้อมูล
    // Output 2 ตอบ HTTP
    return [null, msg];
}

// 1. ตรวจว่ามีการตั้ง API Key ฝั่ง Server
if (!expectedKey || expectedKey.length < 32) {
    return respond(503, {
        success: false,
        error: "Server authentication not configured"
    });
}

// 2. ตรวจ API Key ของอุปกรณ์
if (!receivedKey || receivedKey !== expectedKey) {
    return respond(401, {
        success: false,
        error: "Unauthorized"
    });
}

// 3. อ่าน JSON ที่ ESP32 ส่งมา
let data = msg.payload;

if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (err) {
        return respond(400, {
            success: false,
            error: "Invalid JSON"
        });
    }
}

if (!data || typeof data !== "object" || Array.isArray(data)) {
    return respond(400, {
        success: false,
        error: "Invalid payload"
    });
}

// ตรวจว่าค่าที่ส่งมาเป็นตัวเลขจริง
function validNumber(value, min, max) {
    return typeof value === "number"
        && Number.isFinite(value)
        && value >= min
        && value <= max;
}

let fields = {};
let tags = {
    room: "room308"
};

// 4. ESP32 #1 - DHT22
if (data.device_id === "temp01") {

    if (
        !validNumber(data.temperature, -20, 80) ||
        !validNumber(data.humidity, 0, 100)
    ) {
        return respond(400, {
            success: false,
            error: "Invalid DHT22 values"
        });
    }

    fields = {
        temperature: data.temperature,
        humidity: data.humidity
    };

    tags.device_id = "temp01";
    tags.sensor = "DHT22";


    tags.status = (
    data.temperature > 36 ||
    data.humidity > 85
    ) ? "CRITICAL" : (
    data.temperature > 32 ||
    data.humidity > 75
    ) ? "WARNING" : "NORMAL";


    // 5. ESP32 #2 - PMS5003
} else if (data.device_id === "air01") {

    if (
        !validNumber(data.pm1, 0, 1000) ||
        !validNumber(data.pm25, 0, 1000) ||
        !validNumber(data.pm10, 0, 1000) ||
        data.pm1 > data.pm25 ||
        data.pm25 > data.pm10
    ) {
        return respond(400, {
            success: false,
            error: "Invalid PMS5003 values"
        });
    }

    fields = {
        pm1: data.pm1,
        pm25: data.pm25,
        pm10: data.pm10
    };

    tags.device_id = "air01";
    tags.sensor = "PMS5003";

    // เกณฑ์สาธิตของ EcoDorm
    tags.status = data.pm25 >= 76 ? "CRITICAL"
        : data.pm25 > 35 ? "WARNING"
            : "NORMAL";

} else {
    return respond(400, {
        success: false,
        error: "Unknown device_id"
    });
}

// 6. ส่งข้อมูลไป InfluxDB
const dbMessage = {
    payload: [fields, tags]
};

// 7. ตอบกลับอุปกรณ์ว่า Server รับข้อมูลไว้ประมวลผล
msg.statusCode = 202;
msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    success: true,
    accepted: true,
    device_id: data.device_id
};

// Output 1 = InfluxDB
// Output 2 = HTTP Response
return [dbMessage, msg];

const data = msg.payload;

// 1. ตรวจรูปแบบข้อมูลจาก Validate & Format
if (!Array.isArray(data) || data.length !== 2) {
    return null;
}

const fields = data[0];
const tags = data[1];

if (!fields || !tags) {
    return null;
}

const deviceId = tags.device_id;
const status = tags.status;

// 2. ตรวจ Device และ Status
if (!["temp01", "air01"].includes(deviceId)) {
    return null;
}

if (!["NORMAL", "WARNING", "CRITICAL"].includes(status)) {
    return null;
}

// 3. จำสถานะล่าสุดแยกตามอุปกรณ์
const key = "lastStatus_" + deviceId;
const previousStatus = context.get(key);

// สถานะไม่เปลี่ยน ไม่ต้องแจ้งซ้ำ
if (previousStatus === status) {
    return null;
}

// บันทึกสถานะใหม่
context.set(key, status);

// ครั้งแรกถ้าปกติ ไม่ต้องส่ง Alert
if (previousStatus === undefined && status === "NORMAL") {
    return null;
}

// 4. สร้าง Alert Event
msg.payload = {
    event: status === "NORMAL" ? "RECOVERED" : "ALERT",
    device_id: deviceId,
    sensor: tags.sensor,
    room: tags.room,
    previous_status: previousStatus ?? "UNKNOWN",
    status: status,
    timestamp: new Date().toISOString(),
    readings: fields
};

return msg;

