const data = msg.payload;

// ตรวจรูปแบบข้อมูลจาก Validate & Format
if (!Array.isArray(data) || data.length !== 2) {
    return null;
}

const tags = data[1];
const deviceId = tags?.device_id;

if (!["temp01", "air01"].includes(deviceId)) {
    return null;
}

// บันทึกเวลาที่ได้รับข้อมูลล่าสุด
const now = Date.now();
flow.set("ecodorm_last_seen_" + deviceId, now);

// ตรวจว่าอุปกรณ์เคยถูกประกาศ OFFLINE หรือไม่
const wasOffline =
    flow.get("ecodorm_offline_" + deviceId) === true;

node.status({
    fill: "green",
    shape: "dot",
    text: deviceId + " data received"
});

// ถ้ากลับมาหลัง OFFLINE ให้ส่ง ONLINE event
if (wasOffline) {
    flow.set("ecodorm_offline_" + deviceId, false);

    return {
        topic: "ecodorm/device",
        payload: {
            event: "ONLINE",
            device_id: deviceId,
            room: tags.room || "room308",
            timestamp: new Date(now).toISOString()
        }
    };
}

// ข้อมูลปกติไม่ต้องส่ง Event ทุกนาที
return null;

const devices = ["temp01", "air01"];

const TIMEOUT_MS = 180000; // 180 วินาที
const now = Date.now();

// เวลาที่เริ่มระบบ Monitoring
let monitorStart = flow.get("ecodorm_monitor_start");

if (typeof monitorStart !== "number") {
    monitorStart = now;
    flow.set("ecodorm_monitor_start", monitorStart);
}

let offlineCount = 0;

for (const deviceId of devices) {
    const lastSeen = flow.get(
        "ecodorm_last_seen_" + deviceId
    );

    const isOffline = flow.get(
        "ecodorm_offline_" + deviceId
    ) === true;

    // ถ้ายังไม่เคยได้รับข้อมูล ให้นับจากเวลาเริ่ม Monitoring
    const referenceTime =
        typeof lastSeen === "number"
            ? lastSeen
            : monitorStart;

    const elapsed = now - referenceTime;

    // ขาดข้อมูลเกิน 180 วินาที
    if (elapsed > TIMEOUT_MS && !isOffline) {

        flow.set(
            "ecodorm_offline_" + deviceId,
            true
        );

        offlineCount++;

        node.send({
            topic: "ecodorm/device",
            payload: {
                event: "OFFLINE",
                device_id: deviceId,
                room: "room308",
                last_seen:
                    typeof lastSeen === "number"
                        ? new Date(lastSeen).toISOString()
                        : null,
                offline_for_seconds:
                    Math.floor(elapsed / 1000),
                timestamp: new Date(now).toISOString()
            }
        });
    }
}

node.status({
    fill: offlineCount > 0 ? "red" : "green",
    shape: "dot",
    text: offlineCount > 0
        ? "OFFLINE detected"
        : "Monitoring devices"
});

return null;

const err = msg.error || {};

return {
    topic: "ecodorm/error",
    payload: {
        event: "PROCESSING_ERROR",
        source: err.source?.name || "Unknown",
        message: String(err.message || "Unknown error"),
        timestamp: new Date().toISOString()
    }
};

