const event = msg.payload;

const token = env.get("LINE_CHANNEL_ACCESS_TOKEN");
const userId = env.get("LINE_USER_ID");

if (!token || !userId) {
    node.warn("LINE configuration is missing");
    return null;
}

if (!event || typeof event !== "object") {
    return null;
}

const allowedEvents = [
    "ALERT",
    "RECOVERED",
    "OFFLINE",
    "ONLINE"
];

if (!allowedEvents.includes(event.event)) {
    return null;
}

if (!["temp01", "air01"].includes(event.device_id)) {
    return null;
}

const deviceName = event.device_id === "temp01"
    ? "DHT22 (Temperature / Humidity)"
    : "PMS5003 (Air Quality)";

let title = "";

switch (event.event) {
    case "ALERT":
        if (!["WARNING", "CRITICAL"].includes(event.status)) {
            return null;
        }

        title = event.status === "CRITICAL"
            ? "🚨 CRITICAL ALERT"
            : "⚠️ WARNING ALERT";
        break;

    case "RECOVERED":
        title = "✅ RECOVERED";
        break;

    case "OFFLINE":
        title = "🔴 DEVICE OFFLINE";
        break;

    case "ONLINE":
        title = "🟢 DEVICE ONLINE";
        break;
}

const lines = [
    "🏠 EcoDorm Monitoring",
    title,
    "",
    "Room: " + (event.room || "room308"),
    "Device: " + event.device_id,
    "Sensor: " + deviceName
];

// แสดงค่าที่วัดเมื่อมีข้อมูลเซนเซอร์
const r = event.readings || {};

if (event.device_id === "temp01") {
    if (typeof r.temperature === "number") {
        lines.push("Temperature: " + r.temperature + " °C");
    }

    if (typeof r.humidity === "number") {
        lines.push("Humidity: " + r.humidity + " %");
    }
}

if (event.device_id === "air01") {
    if (typeof r.pm25 === "number") {
        lines.push("PM2.5: " + r.pm25 + " ug/m3");
    }
}

if (event.event === "ALERT" ||
    event.event === "RECOVERED") {
    lines.push("Status: " + event.status);
}

if (event.event === "OFFLINE") {
    lines.push("No sensor data received.");
}

if (event.event === "ONLINE") {
    lines.push("Sensor connection restored.");
}


const eventTime = event.timestamp
    ? new Date(event.timestamp)
    : new Date();

const thaiTime = eventTime.toLocaleString("en-GB", {
    timeZone: "Asia/Bangkok",
    hour12: false
});

lines.push("Time (Thailand): " + thaiTime);


// เตรียมคำขอ LINE Messaging API
msg.headers = {
    "Authorization": "Bearer " + token,
    "Content-Type": "application/json"
};

msg.payload = JSON.stringify({
    to: userId,
    messages: [{
        type: "text",
        text: lines.join("\n")
    }]
});

return msg;
